/* eslint-env node */
const { transform } = require('@svgr/core');
const { camelCase, upperFirst } = require('es-toolkit/compat');
const { optimize } = require('svgo');

/** `utrecht-icon-arrow` becomes `IconArrow` */
const componentName = (id, prefix) => `Icon${upperFirst(camelCase(id.slice(prefix.length)))}`;

/** A `forwardRef` component with the SVG as JSX. `/* @__PURE__ *\/` lets bundlers leave out icons that are not used. */
const template = ({ componentName, jsx }, { tpl }) => tpl`
import { forwardRef, type SVGProps } from 'react';

export const ${componentName} = /* @__PURE__ */ forwardRef<SVGSVGElement, Omit<SVGProps<SVGSVGElement>, 'ref'>>(
  (props, ref) => ${jsx},
);
`;

/**
 * A React component with the SVG as JSX, for one icon, made with SVGR. The ids get the icon id as prefix, so two icons
 * on the same page do not share an id.
 *
 * @param {string} svg An optimized SVG file
 * @param {string} id The icon id, for example `utrecht-icon-arrow`
 * @param {string} prefix The prefix of the icon ids, for example `utrecht-icon-`
 * @returns {{ name: string, source: string }}
 */
exports.reactIcon = (svg, id, prefix) => {
  const { data } = optimize(svg, {
    plugins: [
      { name: 'prefixIds', params: { prefix: id, delim: '-', prefixClassNames: false } },
      // React does not need `xmlns`, and the component sets `aria-hidden` and `focusable` itself
      'removeXMLNS',
      { name: 'removeAttrs', params: { attrs: 'svg:(aria-hidden|focusable)' } },
    ],
  });
  if (!/^<svg\b[^>]*\sviewBox=/.test(data)) throw new Error(`${id}: the <svg> element has no viewBox`);
  if (/\sstyle=/.test(data))
    throw new Error(`${id}: inline \`style\` attributes are not supported, use SVG attributes`);

  const name = componentName(id, prefix);
  const component = transform.sync(
    data,
    {
      plugins: ['@svgr/plugin-jsx'],
      typescript: true,
      ref: true,
      expandProps: 'end',
      // Hidden from assistive technology and not focusable by default, props can override this
      svgProps: { 'aria-hidden': 'true', focusable: 'false' },
      template,
    },
    { componentName: name },
  );

  const source = `/**
 * @license EUPL-1.2
 * Copyright (c) 2021-2026 Gemeente Utrecht
 */

// Generated by @utrecht/icon from the SVG of ${id}, with SVGR. Do not edit this file.
${component}

${name}.displayName = '${name}';
`;
  return { name, source };
};
